const { query } = require('../db');

// Vérifie le jeton de session envoyé dans l'en-tête Authorization.
async function requireAuth(req, res, next) {
  const header = req.get('authorization') || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'Non authentifié' });

  const { rows } = await query(
    'SELECT u.id, u.role FROM sessions s JOIN utilisateurs u ON u.id = s.user_id WHERE s.token = $1 AND s.expire_le > now()',
    [token],
  );
  if (!rows.length) return res.status(401).json({ error: 'Session expirée' });
  req.user = rows[0];
  next();
}

function requireRole(role) {
  return (req, res, next) => (req.user && req.user.role === role ? next() : res.status(403).json({ error: 'Accès refusé' }));
}

module.exports = { requireAuth, requireRole };

const bcrypt = require('bcrypt');

// Facteur de coût bcrypt utilisé pour hacher les mots de passe.
const SALT_ROUNDS = 10;

async function hashPassword(plain) {
  if (typeof plain !== 'string' || plain.length < 8) {
    throw new Error('Mot de passe trop court');
  }
  return bcrypt.hash(plain, SALT_ROUNDS);
}

function verifyPassword(plain, hash) {
  return bcrypt.compare(plain, hash);
}

module.exports = { hashPassword, verifyPassword, SALT_ROUNDS };

const { query } = require('../db');

// Numéro de facture au format F-AAAA-NNNN, séquentiel par année.
async function nextInvoiceNumber(date = new Date()) {
  const year = date.getFullYear();
  const { rows } = await query(
    "SELECT COUNT(*)::int AS n FROM factures WHERE numero LIKE $1",
    [`F-${year}-%`],
  );
  return `F-${year}-${String(rows[0].n + 1).padStart(4, '0')}`;
}

module.exports = { nextInvoiceNumber };

const nodemailer = require('nodemailer');
const { query } = require('../db');
const config = require('../config');

// Nombre de jours après l'échéance avant d'envoyer la relance automatique.
const FIRST_REMINDER_DAYS = 45;

const transport = nodemailer.createTransport({
  host: config.smtp.host,
  port: config.smtp.port,
  auth: { user: config.smtp.user, pass: config.smtp.password },
});

// Envoie une relance par e-mail pour chaque facture en retard depuis
// FIRST_REMINDER_DAYS jours et pas encore relancée.
async function sendDueReminders() {
  const { rows } = await query(
    `SELECT f.id, f.numero, f.montant_ttc, c.contact_email
       FROM factures f JOIN clients c ON c.id = f.client_id
      WHERE f.statut = 'en_retard'
        AND f.date_echeance <= CURRENT_DATE - $1::int
        AND f.nb_relances = 0`,
    [FIRST_REMINDER_DAYS],
  );
  for (const f of rows) {
    await transport.sendMail({
      from: config.invoiceFrom,
      to: f.contact_email,
      subject: `Rappel : facture ${f.numero} en attente de paiement`,
      text: `Bonjour, sauf erreur de notre part, la facture ${f.numero} d'un montant de ${f.montant_ttc} € TTC reste impayée.`,
    });
    await query(
      'UPDATE factures SET nb_relances = nb_relances + 1, derniere_relance = CURRENT_DATE WHERE id = $1',
      [f.id],
    );
  }
  return rows.length;
}

module.exports = { sendDueReminders, FIRST_REMINDER_DAYS };

