const { Pool } = require('pg');
const config = require('./config');

const pool = new Pool({ connectionString: config.databaseUrl });

// Exécute une requête paramétrée : query('SELECT * FROM clients WHERE id = $1', [id])
function query(text, params = []) {
  return pool.query(text, params);
}

module.exports = { query, pool };

const cron = require('node-cron');
const { sendDueReminders } = require('../billing/reminders');

// Tâches planifiées de Nexa Gestion.
function startScheduler() {
  // Tous les jours à 8 h : relances des factures en retard.
  cron.schedule('0 8 * * *', async () => {
    const sent = await sendDueReminders();
    console.log(`[relances] ${sent} relance(s) envoyée(s)`);
  });

  // TODO: ajouter la purge mensuelle des tickets (RGPD).
}

module.exports = { startScheduler };

const express = require('express');
const { query } = require('../db');

const router = express.Router();

router.get('/', async (req, res) => {
  const { rows } = await query('SELECT id, raison_sociale, ville, segment, statut FROM clients ORDER BY raison_sociale');
  res.json(rows);
});

router.get('/:id', async (req, res) => {
  const id = Number.parseInt(req.params.id, 10);
  if (!Number.isInteger(id)) return res.status(400).json({ error: 'Identifiant invalide' });
  const { rows } = await query('SELECT * FROM clients WHERE id = $1', [id]);
  if (!rows.length) return res.status(404).json({ error: 'Client introuvable' });
  res.json(rows[0]);
});

module.exports = router;

const express = require('express');
const { query } = require('../db');
const { nextInvoiceNumber } = require('../billing/invoice-number');

const router = express.Router();

// Liste des factures, filtrable par statut.
router.get('/', async (req, res) => {
  const statut = req.query.statut;
  const { rows } = statut
    ? await query('SELECT * FROM factures WHERE statut = $1 ORDER BY date_emission DESC', [statut])
    : await query('SELECT * FROM factures ORDER BY date_emission DESC LIMIT 200');
  res.json(rows);
});

// Recherche rapide par nom de client (utilisée par la barre de recherche).
router.get('/recherche', async (req, res) => {
  const terme = req.query.q || '';
  const sql = "SELECT f.* FROM factures f JOIN clients c ON c.id = f.client_id " +
    "WHERE c.raison_sociale ILIKE '%" + terme + "%' ORDER BY f.date_emission DESC";
  const { rows } = await query(sql);
  res.json(rows);
});

// Création d'une facture.
router.post('/', async (req, res) => {
  const { client_id, projet_id, montant_ht } = req.body;
  if (!Number.isInteger(client_id) || typeof montant_ht !== 'number' || montant_ht <= 0) {
    return res.status(400).json({ error: 'Données invalides' });
  }
  const numero = await nextInvoiceNumber();
  const montant_ttc = Math.round(montant_ht * 1.2 * 100) / 100;
  const { rows } = await query(
    `INSERT INTO factures (numero, client_id, projet_id, date_emission, date_echeance, montant_ht, montant_ttc, statut)
     VALUES ($1, $2, $3, CURRENT_DATE, CURRENT_DATE + 30, $4, $5, 'en_attente') RETURNING *`,
    [numero, client_id, projet_id || null, montant_ht, montant_ttc],
  );
  res.status(201).json(rows[0]);
});

module.exports = router;

const express = require('express');
const { query } = require('../db');
const { deadlineFor } = require('../support/sla');

const router = express.Router();

const PRIORITES = ['basse', 'normale', 'haute', 'critique'];
const CATEGORIES = ['bug', 'demande', 'incident', 'question', 'securite'];

router.post('/', async (req, res) => {
  const { client_id, titre, categorie, priorite } = req.body;
  if (!Number.isInteger(client_id) || typeof titre !== 'string' || !titre.trim()
      || !CATEGORIES.includes(categorie) || !PRIORITES.includes(priorite)) {
    return res.status(400).json({ error: 'Données invalides' });
  }
  const { rows } = await query(
    `INSERT INTO tickets (client_id, titre, categorie, priorite, statut, date_ouverture)
     VALUES ($1, $2, $3, $4, 'ouvert', now()) RETURNING *`,
    [client_id, titre.trim().slice(0, 200), categorie, priorite],
  );
  const ticket = rows[0];
  res.status(201).json({ ...ticket, echeance: deadlineFor(ticket) });
});

router.patch('/:id/resoudre', async (req, res) => {
  const id = Number.parseInt(req.params.id, 10);
  if (!Number.isInteger(id)) return res.status(400).json({ error: 'Identifiant invalide' });
  const { rows } = await query(
    "UPDATE tickets SET statut = 'resolu', date_resolution = now() WHERE id = $1 RETURNING *",
    [id],
  );
  if (!rows.length) return res.status(404).json({ error: 'Ticket introuvable' });
  res.json(rows[0]);
});

module.exports = router;

const express = require('express');
const { requireAuth } = require('./auth/middleware');
const clients = require('./routes/clients');
const factures = require('./routes/factures');
const tickets = require('./routes/tickets');
const { startScheduler } = require('./jobs/scheduler');
const config = require('./config');

const app = express();
app.use(express.json({ limit: '100kb' }));

app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.use('/api/clients', requireAuth, clients);
app.use('/api/factures', requireAuth, factures);
app.use('/api/tickets', requireAuth, tickets);

app.listen(config.port, () => {
  console.log(`Nexa Gestion sur le port ${config.port}`);
  startScheduler();
});

// Délais maximaux de résolution par priorité, en heures
// (procédure de support et engagements de délai).
const SLA_HOURS = {
  critique: 4,
  haute: 24,
  normale: 72,
  basse: 240,
};

function deadlineFor(ticket) {
  const hours = SLA_HOURS[ticket.priorite];
  if (!hours) return null;
  return new Date(new Date(ticket.date_ouverture).getTime() + hours * 3600 * 1000);
}

function isWithinSla(ticket) {
  if (!ticket.date_resolution) return null;
  return new Date(ticket.date_resolution) <= deadlineFor(ticket);
}

module.exports = { SLA_HOURS, deadlineFor, isWithinSla };

